//! A spec's `Estado:` line, generated by the daemon from the database instead of edited by hand
//! (owner decision F6, option (a), 2026-11-12).
//!
//! The state of a spec lives in `specs`; when the tree a spec launched lands, `settle_land` records
//! the merge (`landed_sha`, `landed_at`, migration 0304) and the driver then rewrites the file's
//! state line from that record. The line is left out of the spec's `content_sha`
//! ([`hashed_view`]), so writing it never makes the scan see an edited spec, send it back to
//! `discovered` and mark its criteria stale. Any other edit still changes the hash.
//!
//! The state line is the first line of the header (the lines before the first `## ` section) that
//! starts, after list, quote or bold markup, with `Estado:`, `Estado**:` or `Estado (`:
//! `**Estado:** ...`, `Estado: ...`, `- **Estado: ...**`, `> **Estado (2026-11-11): ...**`.
//! `Estado anterior:` and `Estados ...` are not it.

use std::borrow::Cow;
use std::ops::Range;
use std::path::Path;

use chrono::{SecondsFormat, Utc};
use sqlx::SqlitePool;

use super::scan::{ScanRoots, resolve_stored_path};

/// The markup before the `Estado` word of a state line (`> `, `- `, `**`) and whether it was bold,
/// or `None` when `body` (a line without its terminator) is not a state line.
fn state_markup(body: &str) -> Option<(&str, bool)> {
    let rest = body.trim_start_matches(['-', '*', '>', ' ', '\t']);
    let after = rest.strip_prefix("Estado")?;
    if !(after.starts_with(':') || after.starts_with('*') || after.starts_with(" (")) {
        return None;
    }
    let lead = &body[..body.len() - rest.len()];
    Some((lead, lead.contains("**")))
}

/// The lines of `text` with their terminators and their byte offset, up to the first `## `
/// section: the header, where a state line and a title may sit.
fn header_lines(text: &str) -> impl Iterator<Item = (usize, &str)> {
    let mut offset = 0;
    text.split_inclusive('\n')
        .map(move |line| {
            let at = offset;
            offset += line.len();
            (at, line)
        })
        .take_while(|(_, line)| !line.trim_start().starts_with("## "))
}

fn body_of(line: &str) -> &str {
    line.trim_end_matches(['\r', '\n'])
}

/// The byte range of the spec's state line in `text`, its terminator included.
pub fn state_line(text: &str) -> Option<Range<usize>> {
    header_lines(text)
        .find(|(_, line)| state_markup(body_of(line)).is_some())
        .map(|(at, line)| at..at + line.len())
}

/// The bytes a spec's `content_sha` is taken over: the file without its state line. A state line
/// that ends the file without a terminator takes the terminator before it, so a line inserted after
/// a title that ends the file leaves the hash where it was too. Bytes that are not UTF-8, or a file
/// with no state line, are hashed as they are.
pub fn hashed_view(bytes: &[u8]) -> Cow<'_, [u8]> {
    let Ok(text) = std::str::from_utf8(bytes) else {
        return Cow::Borrowed(bytes);
    };
    let Some(mut range) = state_line(text) else {
        return Cow::Borrowed(bytes);
    };
    if range.end == text.len() && !text.ends_with('\n') && range.start > 0 {
        let cut = if text[..range.start].ends_with("\r\n") {
            2
        } else {
            1
        };
        range.start -= cut;
    }
    let mut view = Vec::with_capacity(bytes.len() - range.len());
    view.extend_from_slice(&bytes[..range.start]);
    view.extend_from_slice(&bytes[range.end..]);
    Cow::Owned(view)
}

/// What the state line says of a spec whose tree landed: `implementado em master (<sha8>, <YYYY-MM-DD>)`, or
/// `implementado em master (<YYYY-MM-DD>)` when the queue reported no merge sha. `landed_at` is RFC 3339.
/// The word `implementado` stays so `verdict::declares_implemented` still reads a landed spec.
pub fn landed_value(sha: Option<&str>, landed_at: &str) -> String {
    let date = landed_at.get(..10).unwrap_or(landed_at);
    match sha {
        Some(sha) => format!(
            "implementado em master ({}, {date})",
            sha.get(..8).unwrap_or(sha)
        ),
        None => format!("implementado em master ({date})"),
    }
}

/// `text` with its state line saying `value`. An existing line is replaced whole, keeping its
/// list or quote marker, its bold style and its own line ending. With none, `**Estado:** <value>`
/// is inserted right after the title (the first `# ` line of the header), or at the top when there
/// is no title, ending as the file's lines do (CRLF when the file has any, LF otherwise).
pub fn rewrite(text: &str, value: &str) -> String {
    if let Some(range) = state_line(text) {
        let line = &text[range.clone()];
        let body = body_of(line);
        let ending = &line[body.len()..];
        let (lead, bold) = state_markup(body).unwrap_or(("", true));
        let marker = lead.replace('*', "");
        let label = if bold { "**Estado:**" } else { "Estado:" };
        return format!(
            "{}{marker}{label} {value}{ending}{}",
            &text[..range.start],
            &text[range.end..]
        );
    }
    let newline = if text.contains("\r\n") { "\r\n" } else { "\n" };
    let line = format!("**Estado:** {value}");
    let title = header_lines(text).find(|(_, line)| line.starts_with("# "));
    match title {
        Some((at, title)) if title.ends_with('\n') => {
            let end = at + title.len();
            format!("{}{line}{newline}{}", &text[..end], &text[end..])
        }
        // The title is the file's last line, without a terminator.
        Some(_) => format!("{text}{newline}{line}"),
        None => format!("{line}{newline}{text}"),
    }
}

/// Re-keys a spec stored before the state line left the hash: `legacy` (the hash of the whole
/// file) becomes `current` on the spec, its last audit and its criteria, so the scan that first
/// hashes the file without the line finds the spec unchanged.
pub async fn rekey(
    pool: &SqlitePool,
    spec_id: &str,
    legacy: &str,
    current: &str,
) -> Result<(), sqlx::Error> {
    let mut tx = pool.begin_with("BEGIN IMMEDIATE").await?;
    for statement in [
        "UPDATE specs SET content_sha = ? WHERE id = ? AND content_sha = ?",
        "UPDATE specs SET last_audited_sha = ? WHERE id = ? AND last_audited_sha = ?",
        "UPDATE spec_criteria SET spec_sha = ? WHERE spec_id = ? AND spec_sha = ?",
    ] {
        sqlx::query(statement)
            .bind(current)
            .bind(spec_id)
            .bind(legacy)
            .execute(&mut *tx)
            .await?;
    }
    tx.commit().await
}

/// Records on every spec whose tree is `job_id` that the tree landed with merge `sha`. A failure is
/// logged and never fails the landing, which has already happened.
pub async fn record_landed(pool: &SqlitePool, job_id: &str, sha: Option<&str>) {
    let stamp = Utc::now().to_rfc3339_opts(SecondsFormat::Secs, true);
    let result = sqlx::query(
        "UPDATE specs SET landed_sha = ?, landed_at = ?, updated_at = ? WHERE tree_id = ?",
    )
    .bind(sha)
    .bind(&stamp)
    .bind(&stamp)
    .bind(job_id)
    .execute(pool)
    .await;
    if let Err(error) = result {
        tracing::warn!(job = %job_id, %error, "could not record the landing on the job's specs");
    }
}

/// Writes the state line of every spec whose tree `job_id` landed, from what [`record_landed`]
/// stored. The files live in each project's state directory under `machine_root`; a file that
/// cannot be resolved, read or written is logged and skipped, and never fails the landing.
pub async fn write_landed_files(pool: &SqlitePool, machine_root: Option<&Path>, job_id: &str) {
    type Row = (Option<String>, String, Option<String>, String);
    let rows = match sqlx::query_as::<_, Row>(
        "SELECT project_id, path, landed_sha, landed_at FROM specs \
         WHERE tree_id = ? AND landed_at IS NOT NULL",
    )
    .bind(job_id)
    .fetch_all(pool)
    .await
    {
        Ok(rows) => rows,
        Err(error) => {
            tracing::warn!(job = %job_id, %error, "could not read the landed specs of the job");
            return;
        }
    };
    for (project_id, path, sha, landed_at) in rows {
        let value = landed_value(sha.as_deref(), &landed_at);
        if let Err(error) = write_one(machine_root, project_id.as_deref(), &path, &value) {
            tracing::warn!(job = %job_id, %path, %error, "could not write a landed spec's state line");
        }
    }
}

fn write_one(
    machine_root: Option<&Path>,
    project_id: Option<&str>,
    stored: &str,
    value: &str,
) -> Result<(), String> {
    let state_dir = machine_root
        .zip(project_id)
        .and_then(|(root, project)| crate::project::state::dir(root, project));
    let roots = ScanRoots {
        project_root: None,
        state_dir,
    };
    let file = resolve_stored_path(&roots, stored)
        .ok_or_else(|| "the spec file is not under a known state directory".to_owned())?;
    let text = std::fs::read_to_string(&file).map_err(|error| error.to_string())?;
    let updated = rewrite(&text, value);
    if updated != text {
        crate::project::state::write_atomically(&file, &updated)
            .map_err(|error| error.to_string())?;
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::spec_backlog::scan::content_sha;

    const VALUE: &str = "implementado em master (abcd1234, 2026-11-12)";

    #[test]
    fn the_state_line_is_found_in_its_written_forms() {
        for text in [
            "# T\n\n**Estado:** implementado (merge f978cf0f, 2026-08-02)\n",
            "# T\nEstado: implementado\n",
            "# T\n- **Estado: implementada** em `f2b48f3`.\n",
            "# T\n> **Estado (2026-11-11): construído.**\n",
            "# T\n**Estado anterior:** x\n**Estado:** y\n",
        ] {
            let range = state_line(text).unwrap_or_else(|| panic!("no state line in {text:?}"));
            assert!(text[range].contains("Estado"), "{text:?}");
        }
        for text in [
            "# T\n**Estado anterior:** desenho\n",
            "# T\n**Estados vazios:** x\n",
            "# T\nData: 2026-10-22 · Estado: implementado\n",
            "# T\n\n## 1. X\nEstado: implementado\n",
        ] {
            assert_eq!(state_line(text), None, "{text:?}");
        }
    }

    #[test]
    fn the_estado_line_does_not_change_the_content_hash() {
        let before = "# T\n\n**Estado:** aprovado, por implementar\n\n## 1. X\nbody\n";
        let after = rewrite(before, VALUE);
        assert_ne!(after, before);
        assert_eq!(
            content_sha(after.as_bytes()),
            content_sha(before.as_bytes())
        );

        // An inserted line leaves it too, also after a title that ends the file.
        for before in ["# T\n\nbody\n", "# T", "no title\n", "# T\r\n\r\nbody\r\n"] {
            let after = rewrite(before, VALUE);
            assert_ne!(after, before);
            assert_eq!(
                content_sha(after.as_bytes()),
                content_sha(before.as_bytes()),
                "{before:?}"
            );
        }
    }

    #[test]
    fn any_other_edit_still_changes_the_content_hash() {
        let base = "# T\n\n**Estado:** aprovado\n\n## 1. X\nbody\n";
        for edited in [
            "# T2\n\n**Estado:** aprovado\n\n## 1. X\nbody\n",
            "# T\n\n**Estado:** aprovado\n\n## 1. X\nbody changed\n",
            "# T\n**Estado:** aprovado\n\n## 1. X\nbody\n",
            "# T\n\n**Estado anterior:** x\n**Estado:** aprovado\n\n## 1. X\nbody\n",
        ] {
            assert_ne!(
                content_sha(edited.as_bytes()),
                content_sha(base.as_bytes()),
                "{edited:?}"
            );
        }
    }

    #[test]
    fn rewrite_replaces_the_existing_line_in_its_own_form() {
        assert_eq!(
            rewrite("# T\n\n**Estado:** aprovado\n\nbody\n", VALUE),
            format!("# T\n\n**Estado:** {VALUE}\n\nbody\n")
        );
        assert_eq!(
            rewrite("# T\nEstado: aprovado\n", VALUE),
            format!("# T\nEstado: {VALUE}\n")
        );
        assert_eq!(
            rewrite("# T\n- **Estado: implementada** em x\n", VALUE),
            format!("# T\n- **Estado:** {VALUE}\n")
        );
        assert_eq!(
            rewrite("# T\n> **Estado (2026-11-11): x**\n", VALUE),
            format!("# T\n> **Estado:** {VALUE}\n")
        );
        // Idempotent: a second landing with the same record writes nothing new.
        let once = rewrite("# T\n**Estado:** aprovado\n", VALUE);
        assert_eq!(rewrite(&once, VALUE), once);
    }

    #[test]
    fn rewrite_inserts_a_line_after_the_title_when_there_is_none() {
        assert_eq!(
            rewrite("# T\n\nData: 2026-11-12\n", VALUE),
            format!("# T\n**Estado:** {VALUE}\n\nData: 2026-11-12\n")
        );
        assert_eq!(rewrite("# T", VALUE), format!("# T\n**Estado:** {VALUE}"));
        assert_eq!(
            rewrite("body\n", VALUE),
            format!("**Estado:** {VALUE}\nbody\n")
        );
    }

    #[test]
    fn rewrite_keeps_crlf_line_endings() {
        assert_eq!(
            rewrite("# T\r\n\r\n**Estado:** aprovado\r\n\r\nbody\r\n", VALUE),
            format!("# T\r\n\r\n**Estado:** {VALUE}\r\n\r\nbody\r\n")
        );
        assert_eq!(
            rewrite("# T\r\n\r\nbody\r\n", VALUE),
            format!("# T\r\n**Estado:** {VALUE}\r\n\r\nbody\r\n")
        );
    }

    #[test]
    fn landed_value_shortens_the_sha_and_the_stamp() {
        assert_eq!(
            landed_value(Some("abcd1234ef567890"), "2026-11-12T10:00:00Z"),
            VALUE
        );
        assert_eq!(
            landed_value(None, "2026-11-12T10:00:00Z"),
            "implementado em master (2026-11-12)"
        );
    }

    async fn spec_on_tree(pool: &SqlitePool, id: &str, path: &str, tree: &str) {
        sqlx::query(
            "INSERT INTO specs (id, project_id, path, title, content_sha, tree_id, created_at, \
             updated_at) VALUES (?, 'proj-1', ?, 'T', 'sha-1', ?, 'now', 'now')",
        )
        .bind(id)
        .bind(path)
        .bind(tree)
        .execute(pool)
        .await
        .unwrap();
    }

    #[tokio::test]
    async fn a_landed_tree_writes_the_state_line_of_its_specs_and_keeps_their_hash() {
        let pool = crate::testdb::fresh_pool().await;
        let machine = tempfile::tempdir().unwrap();
        let specs = machine.path().join("projects").join("proj-1").join("specs");
        std::fs::create_dir_all(&specs).unwrap();
        let original = "# T\r\n\r\n**Estado:** aprovado\r\n\r\n## 1. X\r\nbody\r\n";
        std::fs::write(specs.join("a.md"), original).unwrap();
        std::fs::write(specs.join("b.md"), original).unwrap();
        spec_on_tree(&pool, "s-a", "<state_dir>/specs/a.md", "job-1").await;
        spec_on_tree(&pool, "s-b", "<state_dir>/specs/b.md", "job-2").await;
        // A spec whose file is gone is logged and skipped.
        spec_on_tree(&pool, "s-c", "<state_dir>/specs/gone.md", "job-1").await;

        record_landed(&pool, "job-1", Some("abcd1234ef567890")).await;
        write_landed_files(&pool, Some(machine.path()), "job-1").await;

        let (sha, at): (Option<String>, Option<String>) =
            sqlx::query_as("SELECT landed_sha, landed_at FROM specs WHERE id = 's-a'")
                .fetch_one(&pool)
                .await
                .unwrap();
        assert_eq!(sha.as_deref(), Some("abcd1234ef567890"));
        let at = at.expect("landed_at");
        let written = std::fs::read_to_string(specs.join("a.md")).unwrap();
        assert_eq!(
            written,
            format!(
                "# T\r\n\r\n**Estado:** implementado em master (abcd1234, {})\r\n\r\n## 1. X\r\nbody\r\n",
                &at[..10]
            )
        );
        assert_eq!(
            content_sha(written.as_bytes()),
            content_sha(original.as_bytes())
        );
        // Another tree's spec is untouched.
        assert_eq!(
            std::fs::read_to_string(specs.join("b.md")).unwrap(),
            original
        );
        let other: Option<String> =
            sqlx::query_scalar("SELECT landed_at FROM specs WHERE id = 's-b'")
                .fetch_one(&pool)
                .await
                .unwrap();
        assert_eq!(other, None);
    }

    #[tokio::test]
    async fn rekey_moves_a_legacy_hash_to_the_current_one() {
        let pool = crate::testdb::fresh_pool().await;
        spec_on_tree(&pool, "s-a", "<state_dir>/specs/a.md", "job-1").await;
        sqlx::query("UPDATE specs SET last_audited_sha = 'sha-1' WHERE id = 's-a'")
            .execute(&pool)
            .await
            .unwrap();
        sqlx::query(
            "INSERT INTO spec_criteria (spec_id, ordinal, text, kind, spec_sha) \
             VALUES ('s-a', 1, 'c', 'behavior', 'sha-1')",
        )
        .execute(&pool)
        .await
        .unwrap();

        rekey(&pool, "s-a", "sha-1", "sha-2").await.unwrap();

        let row: (String, Option<String>) =
            sqlx::query_as("SELECT content_sha, last_audited_sha FROM specs WHERE id = 's-a'")
                .fetch_one(&pool)
                .await
                .unwrap();
        assert_eq!(row, ("sha-2".to_owned(), Some("sha-2".to_owned())));
        let criterion: String =
            sqlx::query_scalar("SELECT spec_sha FROM spec_criteria WHERE spec_id = 's-a'")
                .fetch_one(&pool)
                .await
                .unwrap();
        assert_eq!(criterion, "sha-2");
    }
}
